package chihalu.customstacklimit;

import java.util.HashMap;
import java.util.Map;
import java.util.UUID;

/**
 * プレイヤーごとのスタック数設定を管理するクラス
 */
public class StackLimitConfig {
    private static final Map<UUID, Integer> playerStackLimits = new HashMap<>();
    private static int defaultStackLimit = 64; // デフォルトは通常の64個

    /**
     * プレイヤーのスタック数を設定
     */
    public static void setPlayerStackLimit(UUID playerId, int stackLimit) {
        if (stackLimit > 0) {
            playerStackLimits.put(playerId, stackLimit);
        }
    }

    /**
     * プレイヤーのスタック数を取得
     */
    public static int getPlayerStackLimit(UUID playerId) {
        return playerStackLimits.getOrDefault(playerId, defaultStackLimit);
    }

    /**
     * プレイヤーのスタック数設定を削除（デフォルトに戻す）
     */
    public static void removePlayerStackLimit(UUID playerId) {
        playerStackLimits.remove(playerId);
    }

    /**
     * デフォルトのスタック数を取得
     */
    public static int getDefaultStackLimit() {
        return defaultStackLimit;
    }

    /**
     * 現在のスレッドローカルプレイヤーID（Mixinから使用）
     */
    private static final ThreadLocal<UUID> currentPlayer = new ThreadLocal<>();

    public static void setCurrentPlayer(UUID playerId) {
        currentPlayer.set(playerId);
    }

    public static UUID getCurrentPlayer() {
        return currentPlayer.get();
    }

    public static void clearCurrentPlayer() {
        currentPlayer.remove();
    }
}
